using System;using System.IO;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 string pendingLetterLoad;bool letterLoadReturnsDisk;
 void StartLetterLoad(string name){if(mode==ScreenMode.Edit)return;if(mode!=ScreenMode.Main&&mode!=ScreenMode.Disk)throw new NotSupportedException("G is not verified in this command context.");if(name.Length==0&&NativeDiskDialogChoice.Files){name=ChooseWindowsDiskFile("G");if(name==null)return;}string path=Resolve(name,Directory.GetCurrentDirectory());if(scor4Interface&&mode==ScreenMode.Main){OpenScor4File(path);return;}UpdateDirty();if(dirty&&score.Items.Count>0){pendingLetterLoad=path;letterLoadReturnsDisk=mode==ScreenMode.Disk;Message("Warning: Unsaved Changes will be lost.\r\nLoad new file? (Y/N)");}else LoadLetterFile(path,mode==ScreenMode.Disk);}
 void LoadLetterFile(string path,bool disk,Score incoming=null){if(!originalTextTabNotified){incoming=incoming??Score.Load(path);if(incoming.Items.Exists(item=>item.Code==16&&canvas.TextLayout.HasOriginalTabControl(item.Text))){if(readingCommandFile){originalTextTabNotified=true;}else{originalTextTabContinuation=()=>LoadLetterFile(path,disk,incoming);canvas.BlockItemEditing=true;Message("*** Text tab is set.  Some EDIT or MOVE commands may produce incorrect results."+Environment.NewLine+"Press any key to continue.");command.Clear();return;}}}var previous=score;LoadFile(path,true,incoming);if(scor4Interface&&!Object.ReferenceEquals(previous,score)){scor4FileMenu=false;scor4FileInfoMenu=false;UpdateClassic();}if(disk){if(externalDrawingNameItem!=null)externalDrawingReturnDisk=true;mode=ScreenMode.Disk;UpdateClassic();LayoutClassic();}}
 bool SubmitLetterLoad(string text){if(pendingLetterLoad==null)return false;if(text.Equals("Y",StringComparison.OrdinalIgnoreCase)){string path=pendingLetterLoad;pendingLetterLoad=null;command.Clear();LoadLetterFile(path,letterLoadReturnsDisk);}else if(text.Equals("N",StringComparison.OrdinalIgnoreCase)||text=="\u001b"){pendingLetterLoad=null;command.Clear();Message("");}return true;}
 bool LetterLoadKey(KeyEventArgs key){if(pendingLetterLoad==null)return false;if(key.KeyCode==Keys.Escape){pendingLetterLoad=null;command.Clear();Message("");key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
}}
